INSERT INTO public.resources (id, title, category, type, description, content, readme_content, preview_url, creator_id, difficulty, language, framework, license_type, likes_count, saves_count, downloads_count, views_count, tags) VALUES ('c01f351d-87c3-4391-a8f9-63168f882c65', 'Minimal Responsive Navbar', 'UI/UX', 'Component', 'A complete responsive navigation bar with desktop navigation, mobile hamburger menu, animated mobile drawer, active navigation state, and sticky header.', '{"files":[{"filename":"index.html","extension":".html","language":"HTML","content":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Minimal Responsive Navbar</title>\n  <link rel=\"stylesheet\" href=\"style.css\">\n</head>\n<body>\n  <header class=\"navbar\">\n    <div class=\"container\">\n      <a href=\"#\" class=\"logo\">Brand</a>\n      <nav class=\"desktop-nav\">\n        <ul>\n          <li><a href=\"#\" class=\"active\">Home</a></li>\n          <li><a href=\"#\">About</a></li>\n          <li><a href=\"#\">Services</a></li>\n          <li><a href=\"#\">Contact</a></li>\n        </ul>\n      </nav>\n      <button class=\"mobile-toggle\" aria-label=\"Toggle menu\">\n        <span></span>\n        <span></span>\n        <span></span>\n      </button>\n    </div>\n  </header>\n  <div class=\"mobile-menu\">\n    <ul>\n      <li><a href=\"#\" class=\"active\">Home</a></li>\n      <li><a href=\"#\">About</a></li>\n      <li><a href=\"#\">Services</a></li>\n      <li><a href=\"#\">Contact</a></li>\n    </ul>\n  </div>\n  <script src=\"script.js\"></script>\n</body>\n</html>"},{"filename":"style.css","extension":".css","language":"CSS","content":"/* Long CSS styling */\n:root {\n  --primary: #000;\n  --bg: #fff;\n  --text: #333;\n}\n* { margin: 0; padding: 0; box-sizing: border-box; }\nbody { font-family: system-ui, sans-serif; background: var(--bg); color: var(--text); }\n.navbar { position: fixed; top: 0; width: 100%; background: rgba(255,255,255,0.9); backdrop-filter: blur(10px); z-index: 100; border-bottom: 1px solid #eee; }\n.container { max-width: 1200px; margin: 0 auto; display: flex; justify-content: space-between; align-items: center; padding: 1rem 2rem; }\n.logo { font-size: 1.5rem; font-weight: bold; text-decoration: none; color: var(--primary); }\n.desktop-nav ul { display: flex; list-style: none; gap: 2rem; }\n.desktop-nav a { text-decoration: none; color: var(--text); font-weight: 500; transition: color 0.3s; }\n.desktop-nav a:hover, .desktop-nav a.active { color: var(--primary); }\n.mobile-toggle { display: none; background: none; border: none; cursor: pointer; width: 30px; height: 20px; position: relative; z-index: 101; }\n.mobile-toggle span { display: block; width: 100%; height: 2px; background: var(--primary); position: absolute; transition: 0.3s; }\n.mobile-toggle span:nth-child(1) { top: 0; }\n.mobile-toggle span:nth-child(2) { top: 9px; }\n.mobile-toggle span:nth-child(3) { top: 18px; }\n.mobile-toggle.open span:nth-child(1) { transform: rotate(45deg); top: 9px; }\n.mobile-toggle.open span:nth-child(2) { opacity: 0; }\n.mobile-toggle.open span:nth-child(3) { transform: rotate(-45deg); top: 9px; }\n.mobile-menu { position: fixed; top: 0; right: -100%; width: 100%; height: 100vh; background: var(--bg); display: flex; align-items: center; justify-content: center; transition: right 0.4s ease; z-index: 99; }\n.mobile-menu.open { right: 0; }\n.mobile-menu ul { list-style: none; text-align: center; }\n.mobile-menu li { margin: 2rem 0; }\n.mobile-menu a { font-size: 2rem; text-decoration: none; color: var(--text); }\n@media (max-width: 768px) {\n  .desktop-nav { display: none; }\n  .mobile-toggle { display: block; }\n}"},{"filename":"script.js","extension":".js","language":"JavaScript","content":"const toggle = document.querySelector(''.mobile-toggle'');\nconst menu = document.querySelector(''.mobile-menu'');\n\ntoggle.addEventListener(''click'', () => {\n  toggle.classList.toggle(''open'');\n  menu.classList.toggle(''open'');\n  document.body.style.overflow = menu.classList.contains(''open'') ? ''hidden'' : '''';\n});\n\n// Close menu on link click\ndocument.querySelectorAll(''.mobile-menu a'').forEach(link => {\n  link.addEventListener(''click'', () => {\n    toggle.classList.remove(''open'');\n    menu.classList.remove(''open'');\n    document.body.style.overflow = '''';\n  });\n});"}]}', '# Minimal Responsive Navbar

A modern, responsive navigation bar with a sticky header and mobile drawer menu.

## Features
- Responsive design
- Mobile drawer
- CSS transitions
- Sticky header

## Usage
Just copy the HTML, CSS, and JS into your project.', 'https://images.unsplash.com/photo-1507238692062-58751aa51417?auto=format&fit=crop&w=800&q=80', '0ed76ff0-2edf-49b3-8617-6511a656820c', 'Beginner', 'JavaScript', 'React', 'MIT', 678, 535, 2546, 1883, '["Modern","Responsive","Clean"]');
INSERT INTO public.resources (id, title, category, type, description, content, readme_content, preview_url, creator_id, difficulty, language, framework, license_type, likes_count, saves_count, downloads_count, views_count, tags) VALUES ('65639abc-ab1f-4f64-93c5-64436c330386', 'Modern SaaS Dashboard Sidebar', 'UI/UX', 'Project', 'A premium quality implementation of Modern SaaS Dashboard Sidebar. Ready for production use with best practices, responsive design, and clean code architecture.', '{"files":[{"filename":"App.jsx","extension":".jsx","language":"JavaScript","content":"// ----------------------------------------------------\n// Modern SaaS Dashboard Sidebar\n// ----------------------------------------------------\nimport React, { useState, useEffect } from ''react'';\n\nexport default function App() {\n  const [state, setState] = useState(null);\n\n  useEffect(() => {\n    // Initialization logic\n    console.log(\"Component mounted\");\n  }, []);\n\n  return (\n    <div className=\"container mx-auto p-4\">\n      <header className=\"mb-8\">\n        <h1 className=\"text-3xl font-bold\">Modern SaaS Dashboard Sidebar</h1>\n        <p className=\"text-gray-500\">Built for scale and performance.</p>\n      </header>\n      \n      <main className=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n        <section className=\"bg-white rounded-xl shadow-sm border border-gray-100 p-6\">\n          <h2 className=\"text-xl font-semibold mb-4\">Main Interface</h2>\n          <div className=\"h-64 bg-gray-50 rounded-lg flex items-center justify-center border border-dashed border-gray-200\">\n            <span className=\"text-gray-400\">Content Area</span>\n          </div>\n        </section>\n        \n        <section className=\"bg-white rounded-xl shadow-sm border border-gray-100 p-6\">\n          <h2 className=\"text-xl font-semibold mb-4\">Settings</h2>\n          <form className=\"space-y-4\">\n            <div>\n              <label className=\"block text-sm font-medium text-gray-700\">Option 1</label>\n              <input type=\"text\" className=\"mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500\" />\n            </div>\n            <div>\n              <label className=\"block text-sm font-medium text-gray-700\">Option 2</label>\n              <input type=\"checkbox\" className=\"mt-1 rounded text-indigo-600 focus:ring-indigo-500\" />\n            </div>\n            <button type=\"button\" className=\"w-full bg-black text-white py-2 rounded-md hover:bg-gray-800 transition\">Save Changes</button>\n          </form>\n        </section>\n      </main>\n    </div>\n  );\n}\n"},{"filename":"utils.js","extension":".js","language":"JavaScript","content":"export function helper() { return true; }\n\n// Added lines to make it realistic\nconst MAX_RETRIES = 3;\n\nexport const retry = async (fn) => {\n  let lastError;\n  for(let i = 0; i < MAX_RETRIES; i++) {\n    try {\n      return await fn();\n    } catch(e) {\n      lastError = e;\n      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));\n    }\n  }\n  throw lastError;\n};"},{"filename":"package.json","extension":".json","language":"JSON","content":"{\n  \"name\": \"project\",\n  \"version\": \"1.0.0\",\n  \"dependencies\": {\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  }\n}"}]}', '# Modern SaaS Dashboard Sidebar

## Overview
This project provides a complete solution for Modern SaaS Dashboard Sidebar.

## Installation
```bash
npm install
npm start
```

## Features
- Scalable architecture
- Clean code
- Production ready

## License
