INSERT INTO public.resources (id, title, category, type, description, content, readme_content, preview_url, creator_id, difficulty, language, framework, license_type, likes_count, saves_count, downloads_count, views_count, tags) VALUES ('330b83d3-2abb-45fa-8267-ba9cb28addbf', 'Modern Authentication UI', 'Website Development', 'Project', 'A premium quality implementation of Modern Authentication UI. Ready for production use with best practices, responsive design, and clean code architecture.', '{"files":[{"filename":"App.jsx","extension":".jsx","language":"JavaScript","content":"// ----------------------------------------------------\n// Modern Authentication UI\n// ----------------------------------------------------\nimport React, { useState, useEffect } from ''react'';\n\nexport default function App() {\n  const [state, setState] = useState(null);\n\n  useEffect(() => {\n    // Initialization logic\n    console.log(\"Component mounted\");\n  }, []);\n\n  return (\n    <div className=\"container mx-auto p-4\">\n      <header className=\"mb-8\">\n        <h1 className=\"text-3xl font-bold\">Modern Authentication UI</h1>\n        <p className=\"text-gray-500\">Built for scale and performance.</p>\n      </header>\n      \n      <main className=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n        <section className=\"bg-white rounded-xl shadow-sm border border-gray-100 p-6\">\n          <h2 className=\"text-xl font-semibold mb-4\">Main Interface</h2>\n          <div className=\"h-64 bg-gray-50 rounded-lg flex items-center justify-center border border-dashed border-gray-200\">\n            <span className=\"text-gray-400\">Content Area</span>\n          </div>\n        </section>\n        \n        <section className=\"bg-white rounded-xl shadow-sm border border-gray-100 p-6\">\n          <h2 className=\"text-xl font-semibold mb-4\">Settings</h2>\n          <form className=\"space-y-4\">\n            <div>\n              <label className=\"block text-sm font-medium text-gray-700\">Option 1</label>\n              <input type=\"text\" className=\"mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500\" />\n            </div>\n            <div>\n              <label className=\"block text-sm font-medium text-gray-700\">Option 2</label>\n              <input type=\"checkbox\" className=\"mt-1 rounded text-indigo-600 focus:ring-indigo-500\" />\n            </div>\n            <button type=\"button\" className=\"w-full bg-black text-white py-2 rounded-md hover:bg-gray-800 transition\">Save Changes</button>\n          </form>\n        </section>\n      </main>\n    </div>\n  );\n}\n"},{"filename":"utils.js","extension":".js","language":"JavaScript","content":"export function helper() { return true; }\n\n// Added lines to make it realistic\nconst MAX_RETRIES = 3;\n\nexport const retry = async (fn) => {\n  let lastError;\n  for(let i = 0; i < MAX_RETRIES; i++) {\n    try {\n      return await fn();\n    } catch(e) {\n      lastError = e;\n      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));\n    }\n  }\n  throw lastError;\n};"},{"filename":"package.json","extension":".json","language":"JSON","content":"{\n  \"name\": \"project\",\n  \"version\": \"1.0.0\",\n  \"dependencies\": {\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  }\n}"}]}', '# Modern Authentication UI

