m font-medium text-gray-700\">Option 1</label>\n              <input type=\"text\" className=\"mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-indigo-500 focus:ring-indigo-500\" />\n            </div>\n            <div>\n              <label className=\"block text-sm font-medium text-gray-700\">Option 2</label>\n              <input type=\"checkbox\" className=\"mt-1 rounded text-indigo-600 focus:ring-indigo-500\" />\n            </div>\n            <button type=\"button\" className=\"w-full bg-black text-white py-2 rounded-md hover:bg-gray-800 transition\">Save Changes</button>\n          </form>\n        </section>\n      </main>\n    </div>\n  );\n}\n"},{"filename":"utils.js","extension":".js","language":"JavaScript","content":"export function helper() { return true; }\n\n// Added lines to make it realistic\nconst MAX_RETRIES = 3;\n\nexport const retry = async (fn) => {\n  let lastError;\n  for(let i = 0; i < MAX_RETRIES; i++) {\n    try {\n      return await fn();\n    } catch(e) {\n      lastError = e;\n      await new Promise(r => setTimeout(r, 1000 * Math.pow(2, i)));\n    }\n  }\n  throw lastError;\n};"},{"filename":"package.json","extension":".json","language":"JSON","content":"{\n  \"name\": \"project\",\n  \"version\": \"1.0.0\",\n  \"dependencies\": {\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  }\n}"}]}', '# Tailwind UI Component Collection

